//! Depender plugin — tracks init count via AtomicU32.
//!
//! This is a hand-written test plugin (not generated by polyplugc).
//! It implements the "depender.test@1" contract: init_count() -> u32.
//! Depends on reload.test@1. Used to test cascade reload behavior.

use core::sync::atomic::AtomicU32;
use core::sync::atomic::Ordering;
use polyplug_abi::*;

// ─── Function pointer wrapper for Sync ─────────────────────────────────────────

/// Wrapper for a function pointer stored in a static vtable array.
/// The pointer is 'static (lifetime of the plugin binary) and read-only.
#[repr(transparent)]
pub struct FnPtr(pub *const ());

// SAFETY: FnPtr wraps a 'static function pointer. Function pointers are safe
// to share across threads — the function itself handles its own synchronization.
unsafe impl Send for FnPtr {}
// SAFETY: Function pointers are inherently Sync — multiple threads may call the
// same function concurrently. The underlying data is read-only 'static memory.
unsafe impl Sync for FnPtr {}

// ─── Plugin-specific state and constants ────────────────────────────────────────

// Tracks how many times polyplug_init was called (for cascade reload test).
static INIT_COUNT: AtomicU32 = AtomicU32::new(0_u32);

// DEPENDER_TEST_CONTRACT_ID = fnv1a_64(b"depender.test@1") = 0x54DC2212C30F900D
const DEPENDER_TEST_CONTRACT_ID: u64 = 0x54DC2212C30F900D_u64;

const POLYPLUG_ABI_VERSION: u32 = 1_u32;

// SAFETY: init_count_fn is a C-compatible function with no side effects.
unsafe extern "C" fn init_count_fn() -> u32 {
    INIT_COUNT.load(Ordering::SeqCst)
}

static FUNCTIONS: [FnPtr; 1] = [FnPtr(init_count_fn as *const ())];

static INTERFACE: PluginInterface = PluginInterface {
    rt_ctx: core::ptr::null(),
    contract_id: DEPENDER_TEST_CONTRACT_ID,
    contract_version: 1_u32 << 16,
    function_count: 1_u32,
    dispatch_type: DispatchType::Native,
    dispatch: PluginDispatch {
        native: NativeDispatch {
            functions: FUNCTIONS.as_ptr() as *const *const (),
        },
    },
};

static DESCRIPTOR: PluginDescriptor = PluginDescriptor {
    name: StringView {
        ptr: b"depender_plugin".as_ptr(),
        len: 15,
    },
    contract_name: StringView {
        ptr: b"depender.test".as_ptr(),
        len: 13,
    },
    version_major: 1_u32,
    version_minor: 0_u32,
    version_patch: 0_u32,
};

#[unsafe(no_mangle)]
pub extern "C" fn polyplug_abi_version() -> u32 {
    POLYPLUG_ABI_VERSION
}

/// Plugin init — called by the loader to register vtables.
///
/// # Safety
/// `rt_ctx` must be a valid opaque pointer to the host runtime context.
/// `host_vtable` must be a valid non-null pointer to a HostVTable from the host.
/// `ctx` must be a valid non-null pointer to a PluginContext from the host.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn polyplug_init(
    rt_ctx: *mut core::ffi::c_void,
    host_vtable: *const HostVTable,
    ctx: *const PluginContext,
) -> AbiError {
    if host_vtable.is_null() {
        return AbiError {
            code: ABI_ERROR_GENERIC,
            message: StringView::null(),
        };
    }
    if ctx.is_null() {
        return AbiError {
            code: ABI_ERROR_GENERIC,
            message: StringView::null(),
        };
    }
    INIT_COUNT.fetch_add(1_u32, Ordering::SeqCst);
    // SAFETY: host_vtable is a valid non-null pointer from the host runtime, outlives this call.
    let host: &HostVTable = unsafe { &*host_vtable };
    // SAFETY: register_plugin is a valid function pointer set by the host.
    // DESCRIPTOR and INTERFACE are 'static.
    unsafe {
        (host.register_plugin)(
            rt_ctx,
            &DESCRIPTOR as *const PluginDescriptor,
            &INTERFACE as *const PluginInterface,
        )
    }
}
